# ============================================================================
# M4b_empirical_IPD_validation.R
# Module 4 empirical half (plasmode / real-IPD resampling):
# On two sets of published appendix IPD, run a "digitization -> Guyot reconstruction" closed loop, using real data distributions
# (real event counts, real censoring, non-Weibull) to test the fidelity of reconstructed absolute risk, complementing M4a parametric simulation
# to jointly determine the A/B thresholds. Reviewers cannot refute this part with "your simulation assumptions are unrealistic".
#
# Data (generated by clean_real_ipd.py; patient-level, de-identified published appendix data):
#   ipd_clean_Li2022_postchemo.csv  columns time_month,event,ctDNA (stage III post-chemo, positive group ~6 events)
#   ipd_clean_Ogaard2022_L1_postOP.csv columns fu_from_lm,event,ctDNA (stage IV mCRC post-op, positive group ~29 events)
#   ipd_clean_Ogaard2022_L3_postACT.csv columns fu_from_lm,event,ctDNA
# Note: these are third-party published appendix data for academic validation only; do not redistribute them as own data (see the data statement).
# Depends on survival,dplyr,tidyr,purrr,readr,ggplot2,future,furrr
# ============================================================================
suppressPackageStartupMessages({
  library(survival);library(dplyr);library(tidyr);library(purrr)
  library(readr);library(ggplot2);library(future);library(furrr)
})
out_dir<-"outputs/M4";dir.create(out_dir,showWarnings=FALSE,recursive=TRUE)
TEST_MODE<-FALSE; MASTER_SEED<-20261013   # RELEASED SETTING: full run with 200 repetitions (set TRUE only for a ~1-minute smoke test; released M4b tables were produced with FALSE)
R_REP<-if(TEST_MODE) 20 else 200           # digitization repetitions per (points x risk table x noise) combination
RELBIAS_TOL<-0.10; MAE_TOL<-0.05; COV_LO<-0.90; COV_HI<-0.98
K_GRID<-c(5,8,12,20,40)
RISK_GRID<-c("full","medium_6m","sparse_12m","none")
NOISE_GRID<-c(0,0.02)

# ---------- Guyot reconstruction (identical to M4a, self-contained) ----------
guyot<-function(times,surv,nr_t,nr_v){
  if(length(times)<3)return(NULL)
  if(times[1]!=0){times<-c(0,times);surv<-c(1,surv)}
  o<-order(times);times<-times[o];surv<-cummin(surv[o]);surv<-pmin(pmax(surv,0),1)
  Sat<-function(t)surv[findInterval(t,times,all.inside=TRUE)]
  et<-numeric(0);es<-integer(0)
  for(i in seq_len(length(nr_t)-1)){
    lo<-nr_t[i];hi<-nr_t[i+1];nlo<-nr_v[i];nhi<-nr_v[i+1]
    if(is.na(nlo)||nlo<=0)next; if(is.na(nhi))nhi<-0
    Slo<-Sat(lo);Shi<-Sat(hi);if(Slo<=0)next
    d<-round(nlo*(1-Shi/Slo));d<-max(0,min(d,nlo));cc<-max(0,nlo-d-nhi)
    if(d>0){z<-seq(lo,hi,length.out=d+2)[-c(1,d+2)];et<-c(et,z);es<-c(es,rep(1L,d))}
    if(cc>0){z<-seq(lo,hi,length.out=cc+2)[-c(1,cc+2)];et<-c(et,z);es<-c(es,rep(0L,cc))}
  }
  if(length(et)==0)return(NULL);data.frame(time=et,status=es)
}
# digitize the real KM by (k points, risk table, noise, jitter), then reconstruct
digit_reconstruct<-function(sf,tmax,k,risk,noise,seed){
  set.seed(seed)
  base<-seq(0,tmax,length.out=k+1)[-1]
  jit<-tmax/(2*k)
  dt<-sort(unique(round(c(0,pmax(0,pmin(tmax,base+runif(k,-jit,jit)))),3)))
  ss<-summary(sf,times=dt,extend=TRUE)
  St<-pmin(pmax(ss$surv+rnorm(length(ss$surv),0,noise),0),1);St<-cummin(St)
  if(risk=="full"){rt<-dt;rv<-summary(sf,times=dt,extend=TRUE)$n.risk
  }else if(risk=="none"){rt<-c(0,tmax);rv<-c(sf$n,max(0,round(sf$n*St[length(St)])))}
  else{step<-if(risk=="medium_6m")6 else 12
       rt<-seq(0,floor(tmax/step)*step,by=step);if(!tmax%in%rt)rt<-c(rt,tmax)
       rv<-summary(sf,times=rt,extend=TRUE)$n.risk}
  guyot(dt[-1],St[-1],rt,rv)
}

# ---------- read real IPD ----------
datasets<-list(
  Li2022_postACT_III=list(file="ipd_clean_Li2022_postchemo.csv",tcol="time_month"),
  Ogaard2022_postOP_IV=list(file="ipd_clean_Ogaard2022_L1_postOP.csv",tcol="fu_from_lm"),
  Ogaard2022_postACT_IV=list(file="ipd_clean_Ogaard2022_L3_postACT.csv",tcol="fu_from_lm"))

run_one_dataset<-function(name,cfg){
  d<-read_csv(cfg$file,show_col_types=FALSE);colnames(d)[colnames(d)==cfg$tcol]<-tcol<-"t"
  d<-d%>%filter(!is.na(t),!is.na(ctDNA))
  res<-list();ii<-0
  for(gx in c(0,1)){
    dg<-d%>%filter(ctDNA==gx)
    if(nrow(dg)<10)next
    sf<-survfit(Surv(t,event)~1,data=dg);tmax<-max(dg$t)
    evalT<-c(12,24,36)[c(12,24,36)<=tmax]
    true<-summary(sf,times=evalT,extend=TRUE)
    for(ki in seq_along(K_GRID)) for(ri in seq_along(RISK_GRID)) for(ni in seq_along(NOISE_GRID)){
      k<-K_GRID[ki];risk<-RISK_GRID[ri];noise<-NOISE_GRID[ni]
      for(rep in seq_len(R_REP)){
        rec<-tryCatch(digit_reconstruct(sf,tmax,k,risk,noise,MASTER_SEED+rep*7+ki*100+ri*10+ni),error=function(e)NULL)
        if(is.null(rec))next
        sfr<-survfit(Surv(time,status)~1,data=rec);sr<-summary(sfr,times=evalT,extend=TRUE)
        for(j in seq_along(evalT)){
          ii<-ii+1
          tc<-1-true$surv[j];rc<-1-sr$surv;lcl<-1-sr$upper;ucl<-1-sr$lower
          res[[ii]]<-data.frame(dataset=name,group=gx,n=nrow(dg),events=sum(dg$event),
            k_pts=k,risk=risk,noise=noise,rep=rep,time=evalT[j],true_cir=tc,rec_cir=rc[j],
            lcl=lcl[j],ucl=ucl[j])
        }
      }
    }
  }
  bind_rows(res)
}

plan(multisession,workers=max(1,parallel::detectCores()-1))
# Third-party published appendix IPD are NOT redistributed; run M4b only when
# the cleaned files are present locally (see README). The released thresholds
# table is retained otherwise.
datasets<-datasets[file.exists(vapply(datasets,function(cfg)cfg$file,character(1)))]
if(length(datasets)==0){
  cat("M4b skipped: third-party published appendix IPD not present; released outputs/M4/M4b_empirical_threshold.csv retained (see README).\n")
} else {
all<-future_map_dfr(seq_along(datasets),function(i)run_one_dataset(names(datasets)[i],datasets[[i]]),
                    .options=furrr_options(seed=TRUE,
                      packages=c("survival","dplyr","readr","tidyr","purrr"),
                      globals=c("datasets","run_one_dataset","digit_reconstruct","guyot",
                                "K_GRID","RISK_GRID","NOISE_GRID","R_REP","MASTER_SEED",
                                "RELBIAS_TOL","MAE_TOL","COV_LO","COV_HI")))
plan(sequential)
write_csv(all,file.path(out_dir,"M4b_empirical_all.csv"))

perf<-all%>%mutate(err=rec_cir-true_cir,abserr=abs(err),
  relerr=ifelse(true_cir>0.05,err/true_cir,NA_real_),cover=(true_cir>=lcl&true_cir<=ucl))%>%
  group_by(dataset,group,n,events,k_pts,risk,noise,time)%>%
  summarise(reps=n(),true_cir=mean(true_cir),rec_cir=mean(rec_cir),bias=mean(err),
    relbias=mean(relerr,na.rm=TRUE),mae=mean(abserr),rmse=sqrt(mean(err^2)),
    coverage=mean(cover,na.rm=TRUE),
    pass=(mae<=MAE_TOL&abs(mean(relerr,na.rm=TRUE))<=RELBIAS_TOL&
          mean(cover,na.rm=TRUE)>=COV_LO&mean(cover,na.rm=TRUE)<=COV_HI),.groups="drop")
write_csv(perf,file.path(out_dir,"M4b_empirical_performance.csv"))

# thresholds: pass rate by (positive-group event stratum x points x risk table) across datasets/timepoints (noise=0.02 is more realistic)
thr<-perf%>%filter(group==1,noise==0.02)%>%
  mutate(ev_stratum=cut(events,breaks=c(-1,10,20,Inf),labels=c("positive events<=10","11-20",">20")))%>%
  group_by(ev_stratum,k_pts,risk)%>%
  summarise(pass_rate=mean(pass,na.rm=TRUE),median_MAE=median(mae),median_coverage=median(coverage),.groups="drop")
write_csv(thr,file.path(out_dir,"M4b_empirical_threshold.csv"))

if(!TEST_MODE){
  p<-ggplot(perf%>%filter(group==1,noise==0.02),aes(factor(k_pts),factor(risk,levels=c("full","medium_6m","sparse_12m","none")),fill=mae))+
    geom_tile(color="white")+geom_text(aes(label=sprintf("%.2f",mae)),size=3)+
    facet_wrap(~dataset)+scale_fill_gradient2(low="#2C7BB6",mid="#FFFFBF",high="#D7191C",midpoint=0.05,limits=c(0,0.20),name="MAE")+
    labs(x="digitized points per curve",y="risk-table density",title="Empirical absolute-risk MAE on real IPD (ctDNA+)")+theme_minimal(base_size=11)
  ggsave(file.path(out_dir,"M4b_heatmap_empirical_MAE.png"),p,width=11,height=5,dpi=300)
}
cat("\n===== M4b real-IPD empirical thresholds (positive group, with 0.02 noise)=====\n");print(as.data.frame(thr))
cat("\nDone: ",normalizePath(out_dir),"\n")
cat("Compare this table with M4a M4_threshold_by_events.csv; the most permissive (points x risk table) consistent across both is the grade-A threshold.\n")
} # end else (datasets present)
